def normalize_text(text: str) -> str:
    """
    Performs basic text normalization: lowercases the text and removes punctuation.
    """
    if not isinstance(text, str):
        return ""
    text = text.lower()
    text = ''.join(char for char in text if char.isalnum() or char.isspace())
    return text.strip()
